Summary:
[{
    "SDK_name": "Appodeal Android SDK",
    "API_name": "setChildDirectedTreatment",
    "conditions": ["Should be called before the SDK initialization."],
    "effects": [
        "If called with true, indicates that the content being treated as child-directed for purposes of COPPA i.e., disables sending user data to ad networks.",
        "If called with false, indicates that the content is not treated as child-directed for purposes of COPPA.",
        "If called with null, it will use the COPPA parameter from the application's settings on Appodeal.com."
    ],
    "parameter_configuations": [
      {
        "parameter_values": [true],
        "conditions": [],
        "effects": ["Disables sending user data to ad networks, treating content as child-directed for purposes of COPPA."]
      },
      {
        "parameter_values": [false],
        "conditions": [],
        "effects": ["Content is not treated as child-directed for purposes of COPPA."]
      },
      {
        "parameter_values": [null],
        "conditions": [],
        "effects": ["Uses the COPPA parameter from the application's settings on Appodeal.com"]
      }
    ]
  }]
